std::string error;
void Need(bool ok){if(!ok)throw std::runtime_error(error);}
void Write(const fs::path& path,const std::string& text){fs::create_directories(path.parent_path());std::ofstream f(path,std::ios::binary);f<<text;if(!f)throw std::runtime_error("write "+path.u8string());}
std::string Read(const fs::path& path){std::ifstream f(path,std::ios::binary);if(!f)throw std::runtime_error("read "+path.u8string());return {std::istreambuf_iterator<char>(f),{}};}
AssetId BaseId(const std::string& name){return SceneFingerprintSha256("M76 original Modding Lab:"+name).substr(0,32);}
void Register(const Project& p,const std::string& path,AssetType type,const AssetId& id){Need(AssetDatabase::WriteMeta(p.Resolve(path)+kAssetMetaExtension,id,type,"M76 original/permitted compact lab content",error));}
void Put(const Project& p,const std::string& path,AssetType type,const AssetId& id,const std::string& text){Write(p.Resolve(path),text);Register(p,path,type,id);}
void Bake(const Project& p,Scene& scene){AssetDatabase assets;Need(OpenAuthorAssets(p,assets,error));for(auto& object:scene.Objects())if(object.navigationSurface){NavigationData data;Need(BakeNavigation(scene,object,p.Settings().navigation,data,error,&assets));auto relative="Assets/navigation/landscape.judasnav";fs::create_directories(fs::u8path(p.Resolve(relative)).parent_path());Need(SaveNavigation(p.Resolve(relative),data,error));AssetRecord record;auto* previous=assets.FindByRelativePath(relative);if(previous)record=*previous;else Need(assets.Track(p.Resolve(relative),record,error));object.navigationSurface->asset=record.id;}}
void Ground(Scene& s,const TerrainSource& t){auto& terrain=s.CreateObject("Authored landscape");terrain.id=1;terrain.render.emplace();terrain.render->shape=SceneShape::Mesh;terrain.render->meshAsset=t.meshId;terrain.render->textureAsset=t.textureId;terrain.body.emplace();terrain.body->shape=SceneShape::TriangleMesh;terrain.body->collisionAsset=t.collisionId;auto& nav=s.CreateObject("Navigation frame");nav.id=50;nav.navigationSurface.emplace();nav.navigationSurface->halfExtents={16,6,16};}
void Player(Scene& s,const AssetId& controller,const AssetId& hud,const AssetId& drop){auto& gravity=s.CreateObject("Uniform field");gravity.id=2;gravity.gravity.emplace();gravity.gravity->kind=SceneGravityKind::Uniform;gravity.gravity->regionRadius=300;auto& player=s.CreateObject("Script-controlled visitor");player.id=10;player.transform.position={0,2,9};player.characterMotor.emplace();player.audioListener.emplace();player.audioListener->followActiveView=true;player.ui=SceneUIComponent{hud,"modding_lab",true};SceneScriptSlot slot;slot.asset=controller;slot.properties=JSON({{"hud","modding_lab"},{"drop",drop}}).dump();player.scripts.push_back(slot);auto& start=s.CreateObject("Visitor start");start.id=11;start.playerStart.emplace();start.transform=player.transform;}
void Notice(const Project& p){Write(p.Resolve("NOTICE.txt"),"Original Modding Lab geometry, scripts and textures: CC0. DejaVu Sans retains its accompanying font license.\n");}
std::string Tone(){
 std::string bytes;auto u16=[&](unsigned value){bytes.push_back(char(value));bytes.push_back(char(value>>8));};auto u32=[&](unsigned value){u16(value);u16(value>>16);};
 constexpr unsigned frames=4800;bytes="RIFF";u32(36+frames*2);bytes+="WAVEfmt ";u32(16);u16(1);u16(1);u32(48000);u32(96000);u16(2);u16(16);bytes+="data";u32(frames*2);
 for(unsigned i=0;i<frames;++i){auto value=int16_t(std::sin(double(i)*6.283185307179586*660/48000)*5000*(1-double(i)/frames));u16(uint16_t(value));}return bytes;
}
