 fs::create_directories(fs::u8path(p.Resolve("Assets/fonts")));fs::copy_file(repository/"assets/fonts/DejaVuSans.ttf",p.Resolve("Assets/fonts/DejaVuSans.ttf"));Register(p,"Assets/fonts/DejaVuSans.ttf",AssetType::Font,font);fs::copy_file(repository/"projects/terrain_lab/Assets/fonts/LICENSE.txt",p.Resolve("Assets/fonts/LICENSE.txt"));
 UIDocument doc;UIElement root;root.id="canvas";root.kind=UIKind::Canvas;root.anchorMax={1,1};root.size={0,0};doc.elements.push_back(root);
 UIElement title;title.id="title";title.parent="canvas";title.kind=UIKind::Text;title.font=font;title.offset={24,18};title.size={1100,62};title.text="MODDING LAB | WASD + mouse | Space: jump | E: drop prefab\n1: landscape | 2: mod map | 3: hub | 4: region toggle | F6/F7: save/load | Esc: pause";doc.elements.push_back(title);
 auto status=title;status.id="status";status.offset={24,92};status.size={1100,150};status.text="Loading";doc.elements.push_back(status);
 UIElement pause;pause.id="pause";pause.parent="canvas";pause.kind=UIKind::Panel;pause.anchorMin=pause.anchorMax={.5,.5};pause.offset={-190,-110};pause.size={380,230};pause.background={.04,.08,.12,.96};pause.visible=false;doc.elements.push_back(pause);
 for(int i=0;i<2;++i){UIElement b;b.id=i?"reload":"resume";b.parent="pause";b.kind=UIKind::Button;b.font=font;b.offset={20,25+float(i)*85};b.size={340,65};b.background={.12,.3,.4,1};b.text=i?"RELOAD AUTHORED WORLD":"RESUME";doc.elements.push_back(b);}fs::create_directories(fs::u8path(p.Resolve("Assets/ui")));Need(SaveUIDocument(p.Resolve("Assets/ui/lab.judasui"),doc,error));Register(p,"Assets/ui/lab.judasui",AssetType::UI,hud);
 fs::create_directories(fs::u8path(p.Resolve("Assets/prefabs")));Scene prefab;auto& box=prefab.CreateObject("Ordinary falling prop");box.render.emplace();box.render->color={.9,.55,.15};box.body.emplace();box.body->motion=SceneBodyMotion::Dynamic;Need(SaveSceneToFile(prefab,p.Resolve("Assets/prefabs/drop.judasprefab"),error));Register(p,"Assets/prefabs/drop.judasprefab",AssetType::Prefab,drop);
 auto terrain=CreateTerrain(33,33,32,32);terrain.textureSize=128;terrain.layers.clear();
 for(auto name:{"grass","stone"}){auto id=BaseId(name);auto path=std::string("Assets/textures/")+name+".png";fs::create_directories(fs::u8path(p.Resolve(path)).parent_path());fs::copy_file(repository/"projects/terrain_lab"/path,p.Resolve(path));Register(p,path,AssetType::Texture,id);terrain.layers.push_back({name,id,3});}
 terrain.productDirectory="Assets/Terrain/"+terrain.identity;Write(p.Resolve("Imports/landscape.judasterrain"),SerializeTerrain(terrain));AssetDatabase assets;assets.Scan(p.RootDir(),p.AssetsDir());TerrainCookResult cook;Need(CookTerrain(terrain,p.Resolve("Imports/landscape.judasterrain"),p.RootDir(),assets,cook,error));
 Scene landscape;landscape.Settings().name="Permitted landscape";Ground(landscape,terrain);Player(landscape,controller,hud,drop);Bake(p,landscape);Need(SaveSceneToFile(landscape,p.Resolve("Scenes/landscape.judas"),error));
 Scene hub;hub.Settings().name="Protected hub";auto& floor=hub.CreateObject("Protected game-owned plinth");floor.id=1;floor.transform.position={0,-.5,0};floor.render.emplace();floor.render->halfExtents={18,.5,18};floor.render->color={.08,.17,.23};floor.body.emplace();floor.body->halfExtents=floor.render->halfExtents;Player(hub,controller,hud,drop);auto& marker=hub.CreateObject("Protected monument");marker.id=20;marker.transform.position={6,2,-4};marker.render.emplace();marker.render->halfExtents={1,2,1};marker.render->color={.12,.65,.8};marker.body.emplace();marker.body->halfExtents=marker.render->halfExtents;Need(SaveSceneToFile(hub,p.Resolve("Scenes/main.judas"),error));
