 JSON manifest={{"kind","world"},{"schema",1},{"data",{{"budget",{{"installMilliseconds",2},{"unitsPerFrame",16},{"maxPreparing",2},{"pendingBytes",33554432},{"liveBytes",67108864},{"retainedBytes",4194304},{"resourceCacheBytes",67108864}}},{"regions",JSON::array({regionJSON})},{"references",JSON::array()}}}};
