int main(int argc,char** argv){try{if(argc!=4)throw std::runtime_error("base DEST REPOSITORY | addition KIT DEST | replacement KIT DEST");if(std::string(argv[1])=="base")Base(argv[2],fs::u8path(argv[3]));else if(std::string(argv[1])=="addition")Mod(argv[2],argv[3],false);else if(std::string(argv[1])=="replacement")Mod(argv[2],argv[3],true);else throw std::runtime_error("unknown fixture command");return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
